423→// IsSummarizeEnabled checks if auto-summarize is enabled in this settings instance.
424→func (s *EntireSettings) IsSummarizeEnabled() bool {
425→	if s.StrategyOptions == nil {
426→		return false
427→	}
428→	summarizeOpts, ok := s.StrategyOptions["summarize"].(map[string]any)
429→	if !ok {
430→		return false
431→	}
432→	enabled, ok := summarizeOpts["enabled"].(bool)
433→	if !ok {
434→		return false
435→	}
436→	return enabled
