439→// CheckpointRemoteConfig holds the structured checkpoint remote configuration.
440→// Stored in strategy_options.checkpoint_remote as {"provider": "github", "repo": "org/repo"}.
441→type CheckpointRemoteConfig struct {
442→	Provider string // e.g., "github"
443→	Repo     string // e.g., "org/checkpoints-repo"
444→}
445→
446→// Owner returns the owner portion of the repo field (before the slash).
447→// Returns empty string if the repo field doesn't contain a slash.
448→func (c *CheckpointRemoteConfig) Owner() string {
449→	parts := strings.SplitN(c.Repo, "/", 2)
450→	if len(parts) < 2 {
451→		return ""
452→	}
453→	return parts[0]
454→}
455→
456→// GetCheckpointRemote returns the configured checkpoint remote.
457→// Expects a structured object: {"provider": "github", "repo": "org/repo"}.
458→// Returns nil if not configured, wrong type, or missing required fields.
459→func (s *EntireSettings) GetCheckpointRemote() *CheckpointRemoteConfig {
460→	if s.StrategyOptions == nil {
461→		return nil
462→	}
463→	val, ok := s.StrategyOptions["checkpoint_remote"]
464→	if !ok {
465→		return nil
466→	}
467→	m, ok := val.(map[string]any)
468→	if !ok {
469→		return nil
470→	}
471→	provider, providerOK := m["provider"].(string)
472→	repo, repoOK := m["repo"].(string)
473→	if !providerOK || !repoOK || provider == "" || repo == "" {
474→		return nil
475→	}
476→	if !strings.Contains(repo, "/") {
477→		return nil
478→	}
479→	return &CheckpointRemoteConfig{Provider: provider, Repo: repo}
480→}
