482→// IsCheckpointsV2Enabled checks if checkpoints v2 (dual-write to refs/entire/) is enabled.
483→// Returns false by default if the key is missing or not a bool.
484→func (s *EntireSettings) IsCheckpointsV2Enabled() bool {
485→	if s.StrategyOptions == nil {
486→		return false
487→	}
488→	val, ok := s.StrategyOptions["checkpoints_v2"].(bool)
489→	return ok && val
490→}
