492→// IsPushSessionsDisabled checks if push_sessions is disabled in settings.
493→// Returns true if push_sessions is explicitly set to false.
494→func (s *EntireSettings) IsPushSessionsDisabled() bool {
495→	if s.StrategyOptions == nil {
496→		return false
497→	}
498→	val, exists := s.StrategyOptions["push_sessions"]
499→	if !exists {
500→		return false
501→	}
502→	if boolVal, ok := val.(bool); ok {
503→		return !boolVal // disabled = !push_sessions
504→	}
505→	return false
506→}
