508→// IsExternalAgentsEnabled checks if external agent discovery is enabled in settings.
509→// Returns false by default if settings cannot be loaded or the key is missing.
510→func IsExternalAgentsEnabled(ctx context.Context) bool {
511→	s, err := Load(ctx)
