518→// Save saves the settings to .entire/settings.json.
519→func Save(ctx context.Context, settings *EntireSettings) error {
520→	return saveToFile(ctx, settings, EntireSettingsFile)
521→}
522→
523→// SaveLocal saves the settings to .entire/settings.local.json.
524→func SaveLocal(ctx context.Context, settings *EntireSettings) error {
525→	return saveToFile(ctx, settings, EntireSettingsLocalFile)
526→}
