528→// saveToFile saves settings to the specified file path.
529→func saveToFile(ctx context.Context, settings *EntireSettings, filePath string) error {
530→	// Get absolute path for the file
531→	filePathAbs, err := paths.AbsPath(ctx, filePath)
532→	if err != nil {
533→		filePathAbs = filePath // Fallback to relative
534→	}
535→
536→	// Ensure directory exists
537→	dir := filepath.Dir(filePathAbs)
538→	if err := os.MkdirAll(dir, 0o750); err != nil {
539→		return fmt.Errorf("creating settings directory: %w", err)
540→	}
541→
542→	data, err := jsonutil.MarshalIndentWithNewline(settings, "", "  ")
543→	if err != nil {
544→		return fmt.Errorf("marshaling settings: %w", err)
545→	}
546→
547→	//nolint:gosec // G306: settings file is config, not secrets; 0o644 is appropriate
548→	if err := os.WriteFile(filePathAbs, data, 0o644); err != nil {
549→		return fmt.Errorf("writing settings file: %w", err)
550→	}
551→	return nil
552→}
