14→// ValidateFilter checks that a filter is well-formed.
15→// isBuiltIn distinguishes built-in filters (whose replacements start with __ent__/)
16→// from user filters (whose replacements must start with __ent_user__/).
17→func ValidateFilter(f Filter, isBuiltIn bool) error {
18→	if f.Match == "" {
19→		return errors.New("filter match must be non-empty")
20→	}
21→	if f.Replace == "" {
22→		return errors.New("filter replace must be non-empty")
23→	}
24→	if f.Match == f.Replace {
25→		return errors.New("filter match and replace must be different")
26→	}
27→
28→	// Idempotency: applying clean twice must produce the same result.
29→	// This means the replacement string must not itself contain the match pattern,
30→	// AND the match string must not contain the replacement pattern (which would
31→	// cause smudge to corrupt the match).
32→	if strings.Contains(f.Replace, f.Match) {
33→		return fmt.Errorf("filter replace %q must not contain match %q (not idempotent)", f.Replace, f.Match)
34→	}
35→	if strings.Contains(f.Match, f.Replace) {
36→		return fmt.Errorf("filter match %q must not contain replace %q (smudge would corrupt)", f.Match, f.Replace)
37→	}
38→
39→	if isBuiltIn {
40→		if !strings.HasPrefix(f.Replace, builtInPrefix) {
41→			return fmt.Errorf("built-in filter replace must start with %q, got %q", builtInPrefix, f.Replace)
42→		}
43→	} else {
44→		if !strings.HasPrefix(f.Replace, userPrefix) {
45→			return fmt.Errorf("user filter replace must start with %q, got %q", userPrefix, f.Replace)
46→		}
47→		if len(f.Match) < minMatchLen {
48→			return fmt.Errorf("user filter match must be at least %d characters, got %d", minMatchLen, len(f.Match))
49→		}
50→	}
51→
52→	return nil
53→}
