// Package filter provides clean/smudge transcript filtering for path normalization.
// Transcripts stored in checkpoints contain absolute paths (repo root, home directory)
// which are machine-specific. This package normalizes paths on store (clean) and
// restores them on read (smudge), similar to git's clean/smudge filter pipeline.
package filter

import "bytes"

// Filter defines a single find-and-replace pair used during clean/smudge.
// Clean replaces Match with Replace; Smudge reverses the substitution.
type Filter struct {
	Match   string // literal string to find
	Replace string // literal string to substitute
}

// Clean applies the filter in the "store" direction: Match → Replace.
func (f Filter) Clean(data []byte) []byte {
	return bytes.ReplaceAll(data, []byte(f.Match), []byte(f.Replace))
}

// Smudge applies the filter in the "restore" direction: Replace → Match.
func (f Filter) Smudge(data []byte) []byte {
	return bytes.ReplaceAll(data, []byte(f.Replace), []byte(f.Match))
}

// Pipeline holds an ordered list of filters and applies them collectively.
type Pipeline struct {
	filters []Filter
}

// NewPipeline creates a filter pipeline with built-in path filters and optional user filters.
// Built-in filters (applied first, most-specific first):
//  1. repoRoot → __ent__/repo
//  2. homeDir  → __ent__/home
//
// User filters are appended after built-ins.
func NewPipeline(repoRoot, homeDir string, userFilters []UserFilter) (*Pipeline, error) {
	var filters []Filter

	// Built-in filters, most-specific first (repo root before home dir,
	// since repo root is typically under home dir).
	if repoRoot != "" {
		f := Filter{Match: repoRoot, Replace: "__ent__/repo"}
		if err := ValidateFilter(f, true); err != nil {
			return nil, err
		}
		filters = append(filters, f)
	}
	if homeDir != "" {
		f := Filter{Match: homeDir, Replace: "__ent__/home"}
		if err := ValidateFilter(f, true); err != nil {
			return nil, err
		}
		filters = append(filters, f)
	}

	// User filters
	for _, uf := range userFilters {
		f := Filter{
			Match:   uf.Match,
			Replace: "__ent_user__/" + uf.Key,
		}
		if err := ValidateFilter(f, false); err != nil {
			return nil, err
		}
		filters = append(filters, f)
	}

	return &Pipeline{filters: filters}, nil
}

// UserFilter is the user-facing configuration for a custom transcript filter.
type UserFilter struct {
	Match string // literal string to find
	Key   string // becomes __ent_user__/<key> as the replacement
}

// Clean applies all filters in order (store direction).
func (p *Pipeline) Clean(data []byte) []byte {
	for _, f := range p.filters {
		data = f.Clean(data)
	}
	return data
}

// Smudge applies all filters in reverse order (restore direction).
func (p *Pipeline) Smudge(data []byte) []byte {
	for i := len(p.filters) - 1; i >= 0; i-- {
		data = p.filters[i].Smudge(data)
	}
	return data
}

// CleanString applies Clean to a string value.
func (p *Pipeline) CleanString(s string) string {
	return string(p.Clean([]byte(s)))
}

// SmudgeString applies Smudge to a string value.
func (p *Pipeline) SmudgeString(s string) string {
	return string(p.Smudge([]byte(s)))
}
package filter

import (
	"errors"
	"fmt"
	"strings"
)

const (
	builtInPrefix = "__ent__/"
	userPrefix    = "__ent_user__/"
	minMatchLen   = 8
)

// ValidateFilter checks that a filter is well-formed.
// isBuiltIn distinguishes built-in filters (whose replacements start with __ent__/)
// from user filters (whose replacements must start with __ent_user__/).
func ValidateFilter(f Filter, isBuiltIn bool) error {
	if f.Match == "" {
		return errors.New("filter match must be non-empty")
	}
	if f.Replace == "" {
		return errors.New("filter replace must be non-empty")
	}
	if f.Match == f.Replace {
		return errors.New("filter match and replace must be different")
	}

	// Idempotency: applying clean twice must produce the same result.
	// This means the replacement string must not itself contain the match pattern,
	// AND the match string must not contain the replacement pattern (which would
	// cause smudge to corrupt the match).
	if strings.Contains(f.Replace, f.Match) {
		return fmt.Errorf("filter replace %q must not contain match %q (not idempotent)", f.Replace, f.Match)
	}
	if strings.Contains(f.Match, f.Replace) {
		return fmt.Errorf("filter match %q must not contain replace %q (smudge would corrupt)", f.Match, f.Replace)
	}

	if isBuiltIn {
		if !strings.HasPrefix(f.Replace, builtInPrefix) {
			return fmt.Errorf("built-in filter replace must start with %q, got %q", builtInPrefix, f.Replace)
		}
	} else {
		if !strings.HasPrefix(f.Replace, userPrefix) {
			return fmt.Errorf("user filter replace must start with %q, got %q", userPrefix, f.Replace)
		}
		if len(f.Match) < minMatchLen {
			return fmt.Errorf("user filter match must be at least %d characters, got %d", minMatchLen, len(f.Match))
		}
	}

	return nil
}
package filter

import (
	"context"
	"fmt"
	"os"

	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/settings"
)

// FromContext constructs a Pipeline using the current repo root, home directory,
// and user-configured transcript filters from settings.
func FromContext(ctx context.Context) (*Pipeline, error) {
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return nil, fmt.Errorf("filter: failed to get repo root: %w", err)
	}

	homeDir, err := os.UserHomeDir()
	if err != nil {
		return nil, fmt.Errorf("filter: failed to get home directory: %w", err)
	}

	s, err := settings.Load(ctx)
	if err != nil {
		return nil, fmt.Errorf("filter: failed to load settings: %w", err)
	}

	var userFilters []UserFilter
	for _, tf := range s.TranscriptFilters {
		userFilters = append(userFilters, UserFilter{
			Match: tf.Match,
			Key:   tf.Key,
		})
	}

	return NewPipeline(repoRoot, homeDir, userFilters)
}
