// MustFromContext constructs a Pipeline, returning an error instead of logging.
// Use this when the caller needs to handle the error explicitly.
func MustFromContext(ctx context.Context) (*Pipeline, error) {
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return nil, fmt.Errorf("filter: failed to get repo root: %w", err)
	}

	homeDir, err := os.UserHomeDir()
	if err != nil {
		return nil, fmt.Errorf("filter: failed to get home directory: %w", err)
	}

	s, err := settings.Load(ctx)
	if err != nil {
		return nil, fmt.Errorf("filter: failed to load settings: %w", err)
	}

	return NewPipeline(repoRoot, homeDir, s.TranscriptFilters)
}

