// TestFilter_SmudgeRestoresPathsOnRewind verifies that when rewinding, the
// transcript written to the agent's session file has __ent__/repo replaced back
// with the actual repo root path.
func TestFilter_SmudgeRestoresPathsOnRewind(t *testing.T) {
	t.Parallel()
	env := NewFeatureBranchEnv(t)
	session := env.NewSession()

	env.WriteFile("main.go", "v1")

	if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
		t.Fatalf("SimulateUserPromptSubmit failed: %v", err)
	}

	// Build transcript with repo root paths
	session.TranscriptBuilder.AddUserMessage("Edit " + env.RepoDir + "/main.go")
	session.TranscriptBuilder.AddAssistantMessage("Editing " + env.RepoDir + "/main.go")
	toolID := session.TranscriptBuilder.AddToolUse("mcp__acp__Write", env.RepoDir+"/main.go", "v1")
	session.TranscriptBuilder.AddToolResult(toolID)
	if err := session.TranscriptBuilder.WriteToFile(session.TranscriptPath); err != nil {
		t.Fatalf("failed to write transcript: %v", err)
	}

	if err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {
		t.Fatalf("SimulateStop failed: %v", err)
	}

	// Verify rewind point exists
	points := env.GetRewindPoints()
	if len(points) == 0 {
		t.Fatal("expected at least one rewind point")
	}

	// Make a change so we have something to rewind from
	env.WriteFile("main.go", "v2")

	// Rewind to the checkpoint
	if err := env.Rewind(points[0].ID); err != nil {
		t.Fatalf("Rewind failed: %v", err)
	}

	// Read the restored transcript from the agent session file
	restoredTranscriptPath := filepath.Join(env.ClaudeProjectDir, session.ID+".jsonl")
	restoredData, err := os.ReadFile(restoredTranscriptPath)
	if err != nil {
		t.Fatalf("failed to read restored transcript at %s: %v", restoredTranscriptPath, err)
	}
	restoredContent := string(restoredData)

	// Verify real paths are restored (smudge applied)
	if strings.Contains(restoredContent, "__ent__/repo") {
		t.Errorf("restored transcript should not contain __ent__/repo placeholder, but does:\n%s",
			restoredContent[:min(500, len(restoredContent))])
	}
	if !strings.Contains(restoredContent, env.RepoDir) {
		t.Errorf("restored transcript should contain actual repo root %q, but doesn't:\n%s",
			env.RepoDir, restoredContent[:min(500, len(restoredContent))])
	}
}

// TestFilter_UserFiltersApplied verifies that user-configured transcript_filters
// in settings.json are applied during clean.
func TestFilter_UserFiltersApplied(t *testing.T) {
	t.Parallel()
	env := NewFeatureBranchEnv(t)

	// Add transcript_filters to settings
	settingsPath := filepath.Join(env.RepoDir, ".entire", "settings.json")
	settingsData, err := os.ReadFile(settingsPath)
	if err != nil {
		t.Fatalf("failed to read settings: %v", err)
	}
	var settingsMap map[string]any
	if err := json.Unmarshal(settingsData, &settingsMap); err != nil {
		t.Fatalf("failed to parse settings: %v", err)
	}
	settingsMap["transcript_filters"] = []map[string]string{
		{"match": "secret-hostname.internal", "key": "hostname"},
	}
	updatedData, err := json.MarshalIndent(settingsMap, "", "  ")
	if err != nil {
		t.Fatalf("failed to marshal settings: %v", err)
	}
	if err := os.WriteFile(settingsPath, append(updatedData, '\n'), 0o644); err != nil {
		t.Fatalf("failed to write settings: %v", err)
	}

	session := env.NewSession()
	env.WriteFile("deploy.sh", "#!/bin/bash")

	if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
		t.Fatalf("SimulateUserPromptSubmit failed: %v", err)
	}

	// Build transcript with the hostname that should be filtered
	session.TranscriptBuilder.AddUserMessage("Deploy to secret-hostname.internal")
	session.TranscriptBuilder.AddAssistantMessage("Deploying to secret-hostname.internal now.")
	if err := session.TranscriptBuilder.WriteToFile(session.TranscriptPath); err != nil {
		t.Fatalf("failed to write transcript: %v", err)
	}

	if err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {
		t.Fatalf("SimulateStop failed: %v", err)
	}

	// Commit to trigger condensation
	env.WriteFile("deploy.sh", "#!/bin/bash\necho deployed")
	env.GitAdd("deploy.sh")
	env.SimulatePostCommit(session.ID)

	// Read transcript from metadata branch
	checkpointID := env.GetLatestCheckpointID()
	transcriptPath := checkpointID[:2] + "/" + checkpointID[2:] + "/0/" + paths.TranscriptFileName
	transcriptContent, found := env.ReadFileFromBranch(paths.MetadataBranchName, transcriptPath)
	if !found {
		t.Fatalf("transcript not found on %s at %s", paths.MetadataBranchName, transcriptPath)
	}

	// User filter should have replaced the hostname
	if strings.Contains(transcriptContent, "secret-hostname.internal") {
		t.Errorf("transcript should not contain 'secret-hostname.internal' after filtering, but does")
	}
	if !strings.Contains(transcriptContent, "__ent_user__/hostname") {
		t.Errorf("transcript should contain __ent_user__/hostname placeholder, but doesn't:\n%s",
			transcriptContent[:min(500, len(transcriptContent))])
	}
}

