// TestFilter_RoundTripPreservesContent verifies that clean→commit→rewind→smudge
// produces transcript content identical to the original (paths fully restored).
func TestFilter_RoundTripPreservesContent(t *testing.T) {
	t.Parallel()
	env := NewFeatureBranchEnv(t)

	homeDir, err := os.UserHomeDir()
	if err != nil {
		t.Fatalf("failed to get home dir: %v", err)
	}

	session := env.NewSession()
	env.WriteFile("roundtrip.txt", "test")

	if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
		t.Fatalf("SimulateUserPromptSubmit failed: %v", err)
	}

	// Build transcript with both repo root and home dir paths
	originalMsg := "Edit " + env.RepoDir + "/roundtrip.txt and check " + homeDir + "/.bashrc"
	session.TranscriptBuilder.AddUserMessage(originalMsg)
	session.TranscriptBuilder.AddAssistantMessage("Working on " + env.RepoDir + "/roundtrip.txt")
	toolID := session.TranscriptBuilder.AddToolUse("mcp__acp__Write", env.RepoDir+"/roundtrip.txt", "test content")
	session.TranscriptBuilder.AddToolResult(toolID)
	if err := session.TranscriptBuilder.WriteToFile(session.TranscriptPath); err != nil {
		t.Fatalf("failed to write transcript: %v", err)
	}

	// Save the original transcript content for comparison
	origTranscript, err := os.ReadFile(session.TranscriptPath)
	if err != nil {
		t.Fatalf("failed to read original transcript: %v", err)
	}

	if err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {
		t.Fatalf("SimulateStop failed: %v", err)
	}

	// Rewind to restore the transcript
	points := env.GetRewindPoints()
	if len(points) == 0 {
		t.Fatal("expected rewind points")
	}

	env.WriteFile("roundtrip.txt", "changed")

	if err := env.Rewind(points[0].ID); err != nil {
		t.Fatalf("Rewind failed: %v", err)
	}

	// Read restored transcript
	restoredPath := filepath.Join(env.ClaudeProjectDir, session.ID+".jsonl")
	restoredTranscript, err := os.ReadFile(restoredPath)
	if err != nil {
		t.Fatalf("failed to read restored transcript: %v", err)
	}

	// Both should contain the real paths
	origStr := string(origTranscript)
	restoredStr := string(restoredTranscript)

	if !strings.Contains(origStr, env.RepoDir) {
		t.Error("original transcript should contain repo root")
	}
	if !strings.Contains(restoredStr, env.RepoDir) {
		t.Error("restored transcript should contain repo root (smudge should restore it)")
	}
	if !strings.Contains(restoredStr, homeDir) {
		t.Error("restored transcript should contain home dir (smudge should restore it)")
	}
	if strings.Contains(restoredStr, "__ent__/") {
		t.Error("restored transcript should not contain any __ent__/ placeholders")
	}
}

