897→// When simulateTTY is true, sets ENTIRE_TEST_TTY=1 to simulate a human at the terminal.
898→// When false, filters it out to simulate an agent subprocess (no controlling terminal).
899→func (env *TestEnv) gitCommitWithShadowHooks(message string, simulateTTY bool, files ...string) {
900→	env.T.Helper()
901→
902→	// Stage files using go-git
903→	for _, file := range files {
904→		env.GitAdd(file)
905→	}
906→
907→	// Create a temp file for the commit message (prepare-commit-msg hook modifies this)
908→	msgFile := filepath.Join(env.RepoDir, ".git", "COMMIT_EDITMSG")
909→	if err := os.WriteFile(msgFile, []byte(message), 0o644); err != nil {
910→		env.T.Fatalf("failed to write commit message file: %v", err)
911→	}
912→
913→	// Run prepare-commit-msg hook using the shared binary.
914→	// Pass source="message" to match real `git commit -m` behavior.
915→	prepCmd := exec.Command(getTestBinary(), "hooks", "git", "prepare-commit-msg", msgFile, "message")
916→	prepCmd.Dir = env.RepoDir
917→	if simulateTTY {
