919→		// and askConfirmTTY() return defaultYes without reading from /dev/tty.
920→		prepCmd.Env = append(testutil.GitIsolatedEnv(), "ENTIRE_TEST_TTY=1")
921→	} else {
922→		// Simulate agent: ENTIRE_TEST_TTY=0 makes hasTTY() return false,
923→		// triggering the fast path that adds trailers for ACTIVE sessions.
924→		prepCmd.Env = append(testutil.GitIsolatedEnv(), "ENTIRE_TEST_TTY=0")
925→	}
926→	if output, err := prepCmd.CombinedOutput(); err != nil {
927→		env.T.Logf("prepare-commit-msg output: %s", output)
