// TestFilter_CleanPathsOnShadowBranch verifies that transcript paths are also
// normalized on shadow branches (temporary checkpoints), not just the metadata branch.
func TestFilter_CleanPathsOnShadowBranch(t *testing.T) {
	t.Parallel()
	env := NewFeatureBranchEnv(t)
	session := env.NewSession()

	env.WriteFile("src.go", "package main")

	if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
		t.Fatalf("SimulateUserPromptSubmit failed: %v", err)
	}

	// Build transcript with repo root paths
	session.TranscriptBuilder.AddUserMessage("Edit " + env.RepoDir + "/src.go")
	session.TranscriptBuilder.AddAssistantMessage("Editing " + env.RepoDir + "/src.go")
	if err := session.TranscriptBuilder.WriteToFile(session.TranscriptPath); err != nil {
		t.Fatalf("failed to write transcript: %v", err)
	}

	if err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {
		t.Fatalf("SimulateStop failed: %v", err)
	}

	// Read the transcript from the shadow branch (before any commit/condensation)
	shadowBranch := env.GetShadowBranchName()
	if shadowBranch == "" {
		t.Fatal("shadow branch should exist after stop")
	}

	// The transcript is stored in .entire/metadata/<session-id>/full.jsonl on the shadow branch
	metadataTranscript := ".entire/metadata/" + session.ID + "/" + paths.TranscriptFileName
	shadowContent, found := env.ReadFileFromBranch(shadowBranch, metadataTranscript)
	if !found {
		t.Fatalf("transcript not found on shadow branch %s at %s", shadowBranch, metadataTranscript)
	}

	// Verify repo root is replaced
	if strings.Contains(shadowContent, env.RepoDir) {
		t.Errorf("shadow branch transcript should not contain repo root %q, but does:\n%s",
			env.RepoDir, shadowContent[:min(500, len(shadowContent))])
	}
	if !strings.Contains(shadowContent, "__ent__/repo") {
		t.Errorf("shadow branch transcript should contain __ent__/repo placeholder, but doesn't:\n%s",
			shadowContent[:min(500, len(shadowContent))])
	}
}

// TestFilter_RoundTripPreservesContent verifies that clean→stop→rewind→smudge
// produces transcript content with real paths fully restored.
func TestFilter_RoundTripPreservesContent(t *testing.T) {
	t.Parallel()
	env := NewFeatureBranchEnv(t)

	homeDir, err := os.UserHomeDir()
	if err != nil {
		t.Fatalf("failed to get home dir: %v", err)
	}

	session := env.NewSession()
	env.WriteFile("roundtrip.txt", "test")

	if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
		t.Fatalf("SimulateUserPromptSubmit failed: %v", err)
	}

	// Build transcript with both repo root and home dir paths
	session.TranscriptBuilder.AddUserMessage("Edit " + env.RepoDir + "/roundtrip.txt and check " + homeDir + "/.bashrc")
	session.TranscriptBuilder.AddAssistantMessage("Working on " + env.RepoDir + "/roundtrip.txt")
	toolID := session.TranscriptBuilder.AddToolUse("mcp__acp__Write", env.RepoDir+"/roundtrip.txt", "test content")
	session.TranscriptBuilder.AddToolResult(toolID)
	if err := session.TranscriptBuilder.WriteToFile(session.TranscriptPath); err != nil {
		t.Fatalf("failed to write transcript: %v", err)
	}

	if err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {
		t.Fatalf("SimulateStop failed: %v", err)
	}

	// Rewind to restore the transcript
	points := env.GetRewindPoints()
	if len(points) == 0 {
		t.Fatal("expected rewind points")
	}

	env.WriteFile("roundtrip.txt", "changed")

	if err := env.Rewind(points[0].ID); err != nil {
		t.Fatalf("Rewind failed: %v", err)
	}

	// Read restored transcript
	restoredPath := filepath.Join(env.ClaudeProjectDir, session.ID+".jsonl")
	restoredTranscript, err := os.ReadFile(restoredPath)
	if err != nil {
		t.Fatalf("failed to read restored transcript: %v", err)
	}
	restoredStr := string(restoredTranscript)

	// Real paths should be restored via smudge
	if !strings.Contains(restoredStr, env.RepoDir) {
		t.Error("restored transcript should contain repo root (smudge should restore it)")
	}
	if !strings.Contains(restoredStr, homeDir) {
		t.Error("restored transcript should contain home dir (smudge should restore it)")
	}
	if strings.Contains(restoredStr, "__ent__/") {
		t.Error("restored transcript should not contain any __ent__/ placeholders")
	}
}

